1	//! Which props of a component evidence puts forward (ADR 0028, section A).
2	//!
3	//! [`decide`] is the one place the rules are combined: it takes the [`Evidence`] gathered for the members a
4	//! component's props type reaches and says, for each member, whether it is a typed row or a name in its source's
5	//! layer. It is pure and total: no I/O, no
6	//! name lists, and its output follows the order of the members it is given.
7	//!
8	//! [`apply`] is its one caller, where a structural answer becomes output (`pipeline::revision`): the [`Inputs`]
9	//! gathered with the answer's resolution (so their reads are its dependencies) and the revision's call-site counts
10	//! (counted again each revision, so an edit to a consumer reaches every component it renders). The checker's merges
11	//! keep the inheritance layers, and so the `used` lists, of the structural answer.
12	
13	pub(crate) mod call_sites;
14	pub(crate) mod forwarding;
15	pub(crate) mod props_type;
16	
17	use std::collections::{BTreeMap, BTreeSet};
18	
19	use crate::types::output::{ComponentEntry, InheritedLayer, PropParent};
20	
21	/// The evidence about one component gathered with its resolution: what its props type writes and what its body does.
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub(crate) struct Inputs {
24	    /// The component's place in the project, which its call-site count is looked up by.
25	    pub(crate) site: call_sites::SiteKey,
26	    /// What the props type writes itself.
27	    pub(crate) props_type: props_type::PropsType,
28	    /// What the component's body does with its props; `None` when it has no function of its own.
29	    pub(crate) body: Option<Body>,
30	    /// Whether the listing follows the decision ([`narrow`]): off when every inherited prop is asked for expanded
31	    /// (`collapseInheritedProps: none`, ADR 0028's `relevance: 'all'`); the `used` lists are written either way.
32	    pub(crate) narrows: bool,
33	}
34	
35	/// Decides where each member of `entry`'s props goes, from `inputs`, the revision's `call_sites` of the component and
36	/// the members its listed props and layers reach; keeps the decision on the entry ([`ComponentEntry::relevance`]) and
37	/// lists by it ([`narrow`]).
38	pub(crate) fn apply(entry: &mut ComponentEntry, inputs: &Inputs, call_sites: &CallSites) {
39	    let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
40	    let members = props_type::members(&inputs.props_type, rows, &entry.inheritance);
41	    let shown = decide(&Evidence { members: &members, body: inputs.body.as_ref(), call_sites });
42	    // A row of a member the answer holds only as a name in a collapsed layer (a source the resolver collapsed past its
43	    // thresholds, such as Chakra's `SystemProperties`) has no type to list: it is named in the layer's `used` list
44	    // instead, so a member evidence puts forward is never left unnamed.
45	    let used: BTreeSet<String> = shown
46	        .rows
47	        .iter()
48	        .filter(|name| !entry.props.contains_key(*name) && !entry.notable_inherited.contains_key(*name))
49	        .cloned()
50	        .collect();
51	    // A `Pick` or `Omit` over keys that are not a closed set of literals leaves which members of a source reach
52	    // unproven, so no source is narrowed into a layer that may claim a member that does not reach; React's and the
53	    // DOM's attributes still are, as they are never listed without evidence.
54	    let ambient: BTreeSet<&str> =
55	        members.iter().filter(|member| member.ambient).map(|member| member.name.as_str()).collect();
56	    let declined = inputs.props_type.declined;
57	    let left = if inputs.narrows {
58	        sources(entry, shown.collapsed.iter().filter(|name| !declined || ambient.contains(name.as_str())))
59	    } else {
60	        Vec::new()
61	    };
62	    entry.relevance = Some(std::sync::Arc::new(Placement { left, used }));
63	    narrow(entry);
64	}
65	
66	/// A source by type name and file, as a prop's `parent` and a layer name it.
67	type Source = (String, String);
68	
69	/// Each of `names` with the source the structural answer gives it, grouped by source: the `parent` of the listed prop,
70	/// and the layer of each collapsed layer holding the name. A name the answer gives no source (a listed prop with no
71	/// `parent`) has no entry: its source is unknown, so no lane narrows it. A source of the project has no entry either:
72	/// [`narrow`] never moves a prop of the project's own sources, so naming them would only hold memory.
73	fn sources<'n>(entry: &'n ComponentEntry, names: impl Iterator<Item = &'n String>) -> Vec<(Source, Box<[Box<str>]>)> {
74	    let mut sourced: BTreeMap<(&str, &str), BTreeSet<&str>> = BTreeMap::new();
75	    let mut add = |name: &'n str, type_name: &'n str, file_name: &'n str| {
76	        if crate::origin::declaration_origin(file_name) != crate::origin::Origin::Project {
77	            sourced.entry((type_name, file_name)).or_default().insert(name);
78	        }
79	    };
80	    for name in names {
81	        let listed = entry.props.get(name).or_else(|| entry.notable_inherited.get(name));
82	        if let Some(parent) = listed.and_then(|prop| prop.parent.as_ref()) {
83	            add(name, &parent.name, &parent.file_name);
84	        }
85	        for layer in entry.inheritance.iter().filter(|layer| layer.members.contains(name)) {
86	            add(name, &layer.type_name, &layer.file_name);
87	        }
88	    }
89	    sourced
90	        .into_iter()
91	        .map(|((type_name, file_name), names)| {
92	            ((type_name.to_owned(), file_name.to_owned()), names.into_iter().map(Box::from).collect())
93	        })
94	        .collect()
95	}
96	
97	/// What [`decide`] said of one component, kept on its entry so that every merge of the checker's props into it lists by
98	/// the same decision ([`narrow`]): the decision is made once, from the structural answer's evidence.
99	#[derive(Debug, Clone, Default, PartialEq, Eq)]
100	pub struct Placement {
101	    /// The members evidence leaves out of the listing ([`Shown::collapsed`]), by name under the
102	    /// source the structural answer gives each, sources in order and each source's names sorted: a listed prop is left
103	    /// out only when both match, so a prop of another source with the same name, or one the structural answer gave no
104	    /// source, is never hidden by it. Only sources outside the project are held, the only ones [`narrow`] moves from,
105	    /// and each source's type name and path once per component, not once per name.
106	    left: Vec<(Source, Box<[Box<str>]>)>,
107	    /// The rows [`decide`] puts forward that the structural answer holds only as names in a collapsed layer: named in
108	    /// that layer's `used` list.
109	    used: BTreeSet<String>,
110	}
111	
112	impl Placement {
113	    /// Whether the decision leaves `name`, declared by `parent`, out of the listing.
114	    fn leaves(&self, name: &str, parent: &PropParent) -> bool {
115	        let source = (parent.name.as_str(), parent.file_name.as_str());
116	        self.left
117	            .binary_search_by(|((type_name, file_name), _)| (type_name.as_str(), file_name.as_str()).cmp(&source))
118	            .ok()
119	            .and_then(|at| self.left.get(at))
120	            .is_some_and(|(_, names)| names.binary_search_by(|held| (**held).cmp(name)).is_ok())
121	    }
122	}
123	
124	/// Lists `entry` by its kept [`Placement`]: a listed prop (in `props` or `notableInherited`) the decision leaves out
125	/// and that a source outside the project declares (a dependency's, or React's and the DOM's) moves to the layer of
126	/// its source, as a name, when the placement left out that name from that same source. Its home is the layer of its
127	/// `parent` (by type name and file), else, for an ambient source, the entry's HTML element layer, else a new layer of
128	/// its `parent`. A prop with no `parent` has no known source and stays listed: no name is ever lost. Then each
129	/// layer's `used` list is written. Without a placement (no evidence was gathered) nothing changes. Run by [`apply`] and at the end of each merge of the
130	/// checker's props, which may list again what the structural answer left out.
131	pub(crate) fn narrow(entry: &mut ComponentEntry) {
132	    let Some(placement) = entry.relevance.clone() else { return };
133	    let ComponentEntry { props, notable_inherited, inheritance, .. } = entry;
134	    for listing in [props, notable_inherited] {
135	        listing.retain(|name, prop| {
136	            let Some(parent) = prop.parent.as_ref() else { return true };
137	            if !placement.leaves(name, parent) {
138	                return true;
139	            }
140	            // Only a source outside the project is narrowed: a dependency's or an ambient one, decided by the
141	            // declaring path. The project's own sources stay as the collapse rule lists them.
142	            if crate::origin::declaration_origin(&parent.file_name) == crate::origin::Origin::Project {
143	                return true;
144	            }
145	            // Each name is held once: a layer already holding it keeps it (`listed_props_leave_layers`' rule).
146	            if !inheritance.iter().any(|layer| layer.members.contains(name)) {
147	                home(inheritance, parent).members.push(name.clone());
148	            }
149	            false
150	        });
151	    }
152	    for layer in inheritance.iter_mut() {
153	        layer.total_props = layer.total_props.max(u32::try_from(layer.members.len()).unwrap_or(u32::MAX));
154	        layer.used = layer.members.iter().filter(|name| placement.used.contains(*name)).cloned().collect();
155	    }
156	}
157	
158	/// The layer a prop declared in `parent` is left in ([`narrow`]): made when the entry has none.
159	fn home<'l>(layers: &'l mut Vec<InheritedLayer>, parent: &PropParent) -> &'l mut InheritedLayer {
160	    let ambient = crate::origin::declaration_origin(&parent.file_name).is_ambient();
161	    let at = layers
162	        .iter()
163	        .position(|layer| layer.type_name == parent.name && layer.file_name == parent.file_name)
164	        .or_else(|| {
165	            ambient
166	                .then(|| {
167	                    layers.iter().position(|layer| {
168	                        layer.html_element.is_some() && crate::origin::declaration_origin(&layer.file_name).is_ambient()
169	                    })
170	                })
171	                .flatten()
172	        });
173	    let at = at.unwrap_or_else(|| {
174	        layers.push(InheritedLayer {
175	            type_name: parent.name.clone(),
176	            file_name: parent.file_name.clone(),
177	            omitted: Vec::new(),
178	            html_element: None,
179	            total_props: 0,
180	            members: Vec::new(),
181	            used: Vec::new(),
182	        });
183	        layers.len() - 1
184	    });
185	    &mut layers[at]
186	}
187	
188	/// Everything known about the members one component's props type reaches.
189	#[derive(Debug, Clone, Copy)]
190	pub(crate) struct Evidence<'a> {
191	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
192	    /// once, by its first member.
193	    pub(crate) members: &'a [Member],
194	    /// What the component's own function body does with its props; `None` when it has no function of its own.
195	    pub(crate) body: Option<&'a Body>,
196	    /// The props passed at the component's JSX call sites across the project.
197	    pub(crate) call_sites: &'a CallSites,
198	}
199	
200	/// One member the props type reaches, with the signals its declaration gives.
201	#[derive(Debug, Clone, Default, PartialEq, Eq)]
202	pub(crate) struct Member {
203	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
204	    pub(crate) name: String,
205	    /// The props type declares it itself, not through an inherited source.
206	    pub(crate) own: bool,
207	    /// A key a `Pick<X, …>` names.
208	    pub(crate) picked: bool,
209	    /// It redeclares or narrows a base member.
210	    pub(crate) overrides: bool,
211	    /// It is not optional.
212	    pub(crate) required: bool,
213	    /// Its declaration carries a `@default` tag.
214	    pub(crate) default_tag: bool,
215	    /// It carries a JSDoc comment: orders the rows, never shows a member.
216	    pub(crate) documented: bool,
217	    /// Its type is a union of literals: orders the rows, never shows a member.
218	    pub(crate) literal_union: bool,
219	    /// Declared by React's or the shared DOM declarations ([`crate::origin::Origin::is_ambient`]): decided by
220	    /// the declaring path, never by the name.
221	    pub(crate) ambient: bool,
222	    /// One of a generated set, not an API: a member of a source the resolver collapsed, of a source reaching with more
223	    /// than [`LARGE_API_SOURCE`](crate::types::options::LARGE_API_SOURCE) members, or one a mapped type copies from the
224	    /// keys of an interface of more than [`COLLAPSE_THRESHOLD`](crate::types::options::COLLAPSE_THRESHOLD) members.
225	    /// Decided by structure and size, never by a name.
226	    pub(crate) large: bool,
227	}
228	
229	/// What a component's function body does with its props, read from the syntax alone.
230	#[derive(Debug, Clone, Default, PartialEq, Eq)]
231	pub(crate) struct Body {
232	    /// The props the body reads, destructures (with or without a default) or passes by name. What the body says is
233	    /// certain; its silence is not read: a member it never names keeps the place the props type gives it.
234	    pub(crate) reads: Vec<String>,
235	    /// The JSX elements the body writes, in source order.
236	    pub(crate) elements: Vec<Element>,
237	}
238	
239	/// One JSX element a component body writes.
240	#[derive(Debug, Clone, PartialEq, Eq)]
241	pub(crate) struct Element {
242	    /// What the tag resolves to.
243	    pub(crate) target: Target,
244	    /// Its attributes in source order, so a named attribute's place before or after a spread is kept.
245	    pub(crate) attributes: Vec<Attribute>,
246	}
247	
248	/// What a JSX tag resolves to.
249	#[derive(Debug, Clone, PartialEq, Eq)]
250	pub(crate) enum Target {
251	    /// A host element: a spread onto it passes only ambient DOM attributes.
252	    Dom,
253	    /// A component resolved by symbol and import, with the names of its own non-ambient props.
254	    Component(Vec<String>),
255	    /// A component tag that did not resolve: a spread onto it forwards nothing known.
256	    Unresolved,
257	}
258	
259	/// One attribute of a JSX element.
260	#[derive(Debug, Clone, PartialEq, Eq)]
261	pub(crate) enum Attribute {
262	    /// `name={value}`: set after a spread, it fixes `name`; its value adds nothing.
263	    Named(String),
264	    /// `{...value}`.
265	    Spread(SpreadOf),
266	}
267	
268	/// What a JSX spread attribute spreads.
269	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
270	pub(crate) enum SpreadOf {
271	    /// The props object, whole.
272	    Props,
273	    /// A rest binding of the props object.
274	    Rest,
275	    /// Any other expression: no evidence about the props.
276	    Other,
277	}
278	
279	/// How often each prop is passed at a component's JSX call sites.
280	#[derive(Debug, Clone, Default, PartialEq, Eq)]
281	pub(crate) struct CallSites {
282	    /// The number of call sites.
283	    pub(crate) sites: u32,
284	    /// Each prop passed at them, with the number of sites passing it.
285	    pub(crate) passed: Vec<(String, u32)>,
286	}
287	
288	/// No call sites: no evidence.
289	pub(crate) static NO_CALL_SITES: CallSites = CallSites { sites: 0, passed: Vec::new() };
290	
291	impl CallSites {
292	    /// Whether `count` of the sites reach the floor of `max(2, 20%)` of them.
293	    fn at_floor(&self, count: u32) -> bool {
294	        count >= 2 && u64::from(count) * 5 >= u64::from(self.sites)
295	    }
296	}
297	
298	/// Where [`decide`] puts each member, both lists in the order of [`Evidence::members`], except that `rows` puts the
299	/// documented and literal-union members first.
300	#[derive(Debug, Clone, Default, PartialEq, Eq)]
301	pub(crate) struct Shown {
302	    /// Typed rows.
303	    pub(crate) rows: Vec<String>,
304	    /// Members left as names in their source's layer.
305	    pub(crate) collapsed: Vec<String>,
306	}
307	
308	/// Decides, from the evidence alone, where each member of a component's props goes (ADR 0028, A2):
309	///
310	/// 1. The main props are listed in full: every member the props type declares itself (own, picked, overriding,
311	///    required or defaulted), and every member of a source that is neither ambient nor large ([`Member::large`]), with
312	///    no story or call site needed.
313	/// 2. What the component uses directly is listed from any source: a member its body reads, destructures or passes by
314	///    name, or that a spread forwards to a resolved component's own props. A spread onto a DOM tag is no evidence, and
315	///    a body that hands its props on where the syntax cannot follow promotes nothing and hides nothing.
316	/// 3. Every other member of an ambient or large source stays a name in its layer, unless
317	/// 4. it is passed at the call-site floor (`max(2, 20%)` of the component's call sites).
318	pub(crate) fn decide(evidence: &Evidence<'_>) -> Shown {
319	    let body = evidence.body;
320	    let reads: BTreeSet<&str> = body.map(|body| body.reads.iter().map(String::as_str).collect()).unwrap_or_default();
321	    let forwarded = body.map(Body::forwarded).unwrap_or_default();
322	    let at_floor: BTreeSet<&str> = evidence
323	        .call_sites
324	        .passed
325	        .iter()
326	        .filter(|(_, count)| evidence.call_sites.at_floor(*count))
327	        .map(|(name, _)| name.as_str())
328	        .collect();
329	    let mut shown = Shown::default();
330	    let mut ordered_rows = Vec::new();
331	    let mut placed = BTreeSet::new();
332	    for member in evidence.members {
333	        let name = member.name.as_str();
334	        if !placed.insert(name) {
335	            continue;
336	        }
337	        let declared = member.own || member.picked || member.overrides || member.required || member.default_tag;
338	        let api = !(member.ambient || member.large);
339	        let used = reads.contains(name) || forwarded.contains(name);
340	        if declared || api || used || at_floor.contains(name) {
341	            ordered_rows.push((!(member.documented || member.literal_union), member.name.clone()));
342	        } else {
343	            shown.collapsed.push(member.name.clone());
344	        }
345	    }
346	    ordered_rows.sort_by_key(|(plain, _)| *plain);
347	    shown.rows = ordered_rows.into_iter().map(|(_, name)| name).collect();
348	    shown
349	}
350	
351	impl Body {
352	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
353	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
354	    fn forwarded(&self) -> BTreeSet<&str> {
355	        let mut forwarded = BTreeSet::new();
356	        for element in &self.elements {
357	            let Target::Component(own) = &element.target else { continue };
358	            for (at, attribute) in element.attributes.iter().enumerate() {
359	                if !attribute.spreads_props() {
360	                    continue;
361	                }
362	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
363	                    .iter()
364	                    .filter_map(|after| match after {
365	                        Attribute::Named(name) => Some(name.as_str()),
366	                        Attribute::Spread(_) => None,
367	                    })
368	                    .collect();
369	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
370	            }
371	        }
372	        forwarded
373	    }
374	}
375	
376	impl Attribute {
377	    /// Whether the attribute spreads the props object or a rest binding of it.
378	    fn spreads_props(&self) -> bool {
379	        matches!(self, Self::Spread(SpreadOf::Props | SpreadOf::Rest))
380	    }
381	}
