20	/// How deep [`PropsType::read`] follows aliases of `Pick` keys, so a cyclic alias ends.
21	const MAX_ALIAS_DEPTH: u8 = 8;
22	
23	/// A declaration the props type names, as the caller finds it by name from the component's file.
24	#[derive(Debug, Clone, Copy)]
25	pub(crate) enum Declaration<'a> {
26	    /// An interface.
27	    Interface(&'a CollectedInterface),
28	    /// A type alias.
29	    Alias(&'a CollectedTypeAlias),
30	}
31	
32	/// What a component's props type says itself, read once from its syntax.
33	#[derive(Debug, Clone, Default, PartialEq, Eq)]
34	pub(crate) struct PropsType {
35	    /// The interface the props type is, when it is one: a member whose `parent` it is was declared here.
36	    interface: Option<(String, String)>,
37	    /// The members the props type writes itself: its interface's own members and the fields of its type literals.
38	    own: BTreeSet<String>,
39	    /// The keys a `Pick` in the props type itself names. An `Omit` names nothing kept.
40	    picked: BTreeSet<String>,
41	    /// The props the signature gives a default: a destructuring default or `defaultProps`.
42	    defaulted: BTreeSet<String>,
43	    /// The members the interfaces it extends or intersects declare outside the ambient declarations.
44	    inherited: BTreeSet<String>,
45	    /// A `Pick` or `Omit` in it names keys that are not a finite union of string literals (`string`, a branded or
46	    /// template key): which members reach is not proven, so relevance narrows none of its listing.
47	    pub(crate) declined: bool,
48	}
