225	    /// Whether `parent` is the interface the props type is.
226	    fn declares(&self, parent: &PropParent) -> bool {
227	        self.interface.as_ref().is_some_and(|(name, file)| *name == parent.name && *file == parent.file_name)
228	    }
229	}
