231	/// The props-type evidence of every member a lane's answer reaches: each prop it lists (`rows`, with its
232	/// `notableInherited` ones) in order, then each member of its collapsed `layers` it does not list. `ambient` says
233	/// whether a declaring file is ambient (ADR 0028: by path, never by name); a member with no declaring file is not.
234	/// `large` says whether the member is one of a generated set: a member of a layer (a source the resolver collapsed past
235	/// its thresholds), a member a mapped type copies from a large interface's keys
236	/// ([`ParsedProp::copied_from_large_keys`]), or a member of a source (its `parent`) that has a layer or reaches with
237	/// more than [`LARGE_API_SOURCE`] listed props. A listed prop with no `parent` has no known source and is large only when copied.
238	///
239	/// A member is own when the props type writes it, and overrides when, besides, a base declares it: its `parent` or a
240	/// declaration is not the props type, or a collapsed layer holds it.
241	pub(crate) fn members<'a>(
242	    props_type: &PropsType,
243	    rows: impl IntoIterator<Item = &'a ParsedProp>,
244	    layers: &[InheritedLayer],
245	) -> Vec<Member> {
246	    let ambient = |file: &str| crate::origin::declaration_origin(file).is_ambient();
247	    let layered: BTreeSet<&str> = layers.iter().flat_map(|layer| layer.members.iter().map(String::as_str)).collect();
248	    let mut listed = BTreeSet::new();
249	    let rows: Vec<&ParsedProp> = rows.into_iter().filter(|prop| listed.insert(prop.name.as_str())).collect();
250	    // Each source's reach over the listed props.
251	    let mut reach: BTreeMap<(&str, &str), usize> = BTreeMap::new();
252	    for parent in rows.iter().filter_map(|prop| prop.parent.as_ref()) {
253	        *reach.entry((&parent.name, &parent.file_name)).or_default() += 1;
254	    }
255	    // A listed prop of a source the resolver collapsed (a notable member of its layer) is of that generated set too.
256	    for layer in layers {
257	        reach.insert((&layer.type_name, &layer.file_name), usize::MAX);
258	    }
259	    let large = |parent: &PropParent| {
260	        reach
261	            .get(&(parent.name.as_str(), parent.file_name.as_str()))
262	            .is_some_and(|reaching| *reaching > LARGE_API_SOURCE)
263	    };
264	    let mut members = Vec::new();
265	    for prop in rows {
266	        let own = props_type.own.contains(&prop.name) || prop.parent.as_ref().is_some_and(|p| props_type.declares(p));
267	        let based = layered.contains(prop.name.as_str())
268	            || prop.parent.iter().chain(&prop.declarations).any(|parent| !props_type.declares(parent));
269	        let given = member(props_type, &prop.name);
270	        members.push(Member {
271	            own,
272	            overrides: own && based,
273	            required: prop.required,
274	            default_tag: given.default_tag || prop.default_value.is_some() || prop.tags.contains_key("default"),
275	            documented: !prop.description.is_empty(),
276	            literal_union: is_literal_union(&prop.prop_type),
277	            // The checker states `parent` only for an interface; a declaration in a type literal is still in a file.
278	            ambient: prop.parent.iter().chain(&prop.declarations).any(|parent| ambient(&parent.file_name)),
279	            large: prop.copied_from_large_keys || prop.parent.as_ref().is_some_and(large),
