        let mut rng = Lcg(seed);
        let mut text = String::from(
            "import type { Api } from './sources';\n\
             import type { ReactDom } from './vendor/@types/react/dom';\n\
             export function Child(props: { v?: string }) { return null; }\n",
        );
        let mut expected = Vec::new();
        for c in 0..10 {
