"""Scratch: rows of the biggest components by declaring source. usage: src_of.py <run.json> [n]"""
import collections
import json
import sys

d = json.load(open(sys.argv[1]))
n = int(sys.argv[2]) if len(sys.argv) > 2 else 3
sizes = []
for k, c in d['components'].items():
    rows = {}
    for s in c.get('props') or []:
        rows.update(d['propSets'][s])
    sizes.append((len(rows), k, c, rows))
sizes.sort(key=lambda x: -x[0])
for size, k, c, rows in sizes[:n]:
    by = collections.Counter()
    for name, pid in rows.items():
        p = d['props'][pid]
        par = p.get('parent') or {}
        by[(par.get('name'), (par.get('fileName') or '').split('/')[-1])] += 1
    print(size, k, by.most_common(6), [(l['typeName'], l.get('totalProps')) for l in c.get('inheritance') or []][:6])

